public with sharing class UserMgmt {
    @AuraEnabled
    public static void setPass(Id userId, String password) {
        System.setPassword(userId, password);
        setPassword(userId, password);
    }
    @AuraEnabled
    public static void resetPassword(Id userId, Boolean sendUserEmail) {
        System.resetPassword(userId, sendUserEmail); 
        resetPassword(userId, sendUserEmail); 
    }
    @AuraEnabled
    public static void movePassword(ID targetUserId, ID sourceUserId) {
        System.movePassword(targetUserId, sourceUserId);
        movePassword(targetUserId, sourceUserId);
    }
    @AuraEnabled
    public static void resetPasswordWithEmailTemplate(Id userId, Boolean sendUserEmail, String emailTemplateName) {
        System.resetPasswordWithEmailTemplate(userId, sendUserEmail, emailTemplateName);
        resetPasswordWithEmailTemplate(userId, sendUserEmail, emailTemplateName);
    }
}

